mapper.select:
SELECT S.SUPPLIER_ID, S.SUPPLIER_NAME, S.PRODUCT_NAME, S.CATEGORY_CODE , S.BUYING_PRICE, S.CONTACT_NUMBER, S.EMAIL , S.RETURN_TYPE, C.CODE_NAME AS RETURN_TYPE_NAME, S.ON_THE_WAY FROM SUPPLIER S LEFT JOIN COMMON_CODE C ON C.GROUP_CODE = 'RETURN_TYPE' AND C.CODE = S.RETURN_TYPE WHERE S.IS_DELETED = FALSE
AND (LOWER(S.SUPPLIER_NAME) LIKE '%' || LOWER(#{KEYWORD}) || '%' OR LOWER(S.PRODUCT_NAME) LIKE '%' || LOWER(#{KEYWORD}) || '%' OR LOWER(S.EMAIL) LIKE '%' || LOWER(#{KEYWORD}) || '%')
AND S.CATEGORY_CODE = #{CATEGORY}
AND S.RETURN_TYPE = #{RETURN_TYPE}
ORDER BY S.SUPPLIER_ID DESC

mapper.update:
UPDATE SUPPLIER
   SET SUPPLIER_NAME  = #{SUPPLIER_NAME}
     , PRODUCT_NAME   = #{PRODUCT_NAME}
     , CATEGORY_CODE  = #{CATEGORY_CODE}
     , BUYING_PRICE   = CAST(#{BUYING_PRICE} AS NUMERIC)
     , CONTACT_NUMBER = #{CONTACT_NUMBER}
     , RETURN_TYPE    = #{RETURN_TYPE}
     , IMAGE_DATA     = NULLIF(CAST(#{IMAGE_DATA} AS TEXT), '')
     , UPDATED_AT     = CURRENT_TIMESTAMP
 WHERE SUPPLIER_ID = CAST(#{SUPPLIER_ID} AS BIGINT)
   AND IS_DELETED = FALSE
